package com.gymmind.workout.api; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import com.gymmind.workout.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/v1/workout-records") public class WorkoutRecordController { private final WorkoutRecordService service; private final CurrentActorProvider actors; public WorkoutRecordController(WorkoutRecordService s,CurrentActorProvider a){service=s;actors=a;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<WorkoutRecordView> create(@Valid @RequestBody Request r){return ApiResponse.success(service.create(actors.requireCurrent(),r.toCommand()));} public record Request(Long planId,@NotNull LocalDate workoutDate,@Min(0) int duration,@Min(0) int calories,@NotBlank String notes,@NotEmpty List<SetRequest> sets){CreateWorkoutRecordCommand toCommand(){return new CreateWorkoutRecordCommand(null,planId,workoutDate,duration,calories,notes,sets.stream().map(SetRequest::toCommand).toList());}} public record SetRequest(@NotNull Long exerciseId,@Min(1) int setNumber,@Min(0) double weight,@Min(0) int reps,@Min(0) int duration,boolean completed){WorkoutSetCommand toCommand(){return new WorkoutSetCommand(exerciseId,setNumber,weight,reps,duration,completed);}} }
